/* In your global main.css file */
@tailwind base;
@tailwind components;
@tailwind utilities;

/* Inject custom utilities into Tailwind's engine! */
@layer utilities {
  .no-scrollbar {
    /* Firefox */
    scrollbar-width: none; 
    /* IE 10+ */
    -ms-overflow-style: none; 
  }
  .no-scrollbar::-webkit-scrollbar {
    /* Chrome/Safari/Edge */
    display: none; 
  }
}

/* Now you can use it in HTML, WITH prefixes! */
